using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;
public static class StairAPostPlay {public static object Run(){if(Application.isPlaying)throw new Exception("Stop Play before preserving Edit state");var s=SceneManager.GetActiveScene();string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var dir=Path.Combine(Path.GetTempPath(),"AfterSeconds_StairA_PostPlay_"+DateTime.Now.ToString("yyyyMMdd_HHmmss"));Directory.CreateDirectory(dir);bool dirty=s.isDirty;if(!EditorSceneManager.SaveScene(s,Path.Combine(dir,"editing_before_save.unity"),true))throw new Exception("Backup failed");if(dirty&&!EditorSceneManager.SaveScene(s))throw new Exception("Save failed");string shot="Assets/Temp/StairA_Play_stairs.png";string path=Path.GetFullPath(Path.Combine(Application.dataPath,"..",shot));if(File.Exists(path)){File.Copy(path,repo+"/Docs/검수/2026-11-08_T02_StairA/Play_stairs.png",true);AssetDatabase.DeleteAsset(shot);}var p=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var result=new{backup=dir,preservedDirtyState=dirty,scene=s.path,dirty=s.isDirty,player=new[]{p.transform.position.x,p.transform.position.y,p.transform.position.z},runInBackground=PlayerSettings.runInBackground};File.WriteAllText(repo+"/Docs/검수/2026-11-08_T02_StairA/post_play.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}}
